"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9547],{75032:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"PlacementCameraController","desc":"Takes exclusive ownership of the camera while build mode is active: a\\nfixed-height, fixed-pitch, yaw-locked-at-entry top-down view that follows\\nthe player. Restores Enum.CameraType.Custom on exit. Independent of\\nCameraController (Enum.CameraType.Custom + CameraOffset spring), which is\\nharmlessly inert while this module owns the camera \u2014 it never touches\\nCamera.CFrame or Camera.CameraType.\\n\\nBecause this camera is Scriptable and driven entirely by hrp.Position plus\\na fixed yaw/pitch/height, it does not rotate in response to mouse delta\\nthe way the normal locked third-person camera does. The placement raycast\\naims from the mouse cursor\'s actual on-screen position, so on PC this\\nmodule also frees the cursor (via Signals.RequestMouseIcon) while build\\nmode is active so the player can aim.\\n\\nEntry and exit both ease the camera angle via an exponential chase-lerp\\n(PlacementConfig.CameraTransitionSpeed) instead of snapping instantly. On\\nexit there\'s no live Custom-camera CFrame to blend toward, so it eases\\ntoward an approximation reconstructed from the camera\'s offset relative to\\nhrp at the moment build mode was entered, then hands off to\\nEnum.CameraType.Custom once that blend has settled.","realm":["Client"],"source":{"line":29,"path":"src/StarterPlayer/StarterPlayerScripts/PlacementCameraController.client.luau"}}')}}]);